import { Avatar, AvatarGroup, AvatarFallback, AvatarImage } from '@astrale-os/ui/avatar'
import { Tooltip, TooltipContent, TooltipTrigger } from '@astrale-os/ui/tooltip'

const avatars = [
  {
    src: 'https://cdn.shadcnstudio.com/ss-assets/avatar/avatar-3.png',
    fallback: 'OS',
    name: 'Olivia Sparks'
  },
  {
    src: 'https://cdn.shadcnstudio.com/ss-assets/avatar/avatar-6.png',
    fallback: 'HL',
    name: 'Howard Lloyd'
  },
  {
    src: 'https://cdn.shadcnstudio.com/ss-assets/avatar/avatar-5.png',
    fallback: 'HR',
    name: 'Hallie Richards'
  },
  {
    src: 'https://cdn.shadcnstudio.com/ss-assets/avatar/avatar-16.png',
    fallback: 'JW',
    name: 'Jenny Wilson'
  }
]

const AvatarGroupTooltipDemo = () => {
  return (
    <AvatarGroup className='**:data-[slot=avatar]:ring-background **:data-[slot=avatar]:ring-2'>
      {avatars.map((avatar, index) => (
        <Tooltip key={index}>
          <TooltipTrigger>
            <Avatar className='transition-all duration-300 ease-in-out hover:z-1 hover:-translate-y-1 hover:shadow-md'>
              <AvatarImage src={avatar.src} alt={avatar.name} />
              <AvatarFallback>{avatar.fallback}</AvatarFallback>
            </Avatar>
          </TooltipTrigger>
          <TooltipContent>{avatar.name}</TooltipContent>
        </Tooltip>
      ))}
    </AvatarGroup>
  )
}

export default AvatarGroupTooltipDemo
